-- Тема 09: правки по отчёту Codex (20 исправлений в 8 вопросах), ключи не меняются.
-- Источник: scripts/questions/102_codex_topic09_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Почему не рекомендуется создавать собственные объекты с именами на pg_?', NULL, NULL, NULL, 'Почему не рекомендуется давать собственным таблицам имена с префиксом pg_?'),
        ('option', 'Чем information_schema отличается от pg_catalog?', 'Доступна для чтения суперпользователю кластера', 'Обновляется с задержкой после изменений каталога', 'Доступна всем и показывает объекты, к которым есть доступ.', 'Это представления над pg_catalog, они всегда показывают текущее состояние каталога.'),
        ('option', 'Чем information_schema отличается от pg_catalog?', 'Определена стандартом SQL, не описывает особенности PostgreSQL', 'Определена стандартом SQL, без особенностей PostgreSQL', NULL, NULL),
        ('option', 'Как обычно устроены имена столбцов в таблицах системного каталога?', 'Имена столбцов по стандарту SQL', 'Имена, заданные стандартом SQL', 'Такие имена используются в information_schema.', 'Стандарт задаёт имена столбцов information_schema, а в pg_catalog их определяет PostgreSQL.'),
        ('option', 'Как обычно устроены имена столбцов в таблицах системного каталога?', 'Короткий префикс без подчёркивания (datname)', 'Короткий префикс без подчёркивания', NULL, NULL),
        ('option', 'Как обычно устроены имена столбцов в таблицах системного каталога?', 'Префикс pg_ у каждого столбца таблицы', 'Префикс pg_ в начале имени столбца', NULL, NULL),
        ('option', 'Что появилось у большинства таблиц системного каталога начиная с PostgreSQL 14?', 'Внешние ключи между таблицами каталога', 'Ограничения FOREIGN KEY между таблицами каталога', 'Настоящих внешних ключей в системном каталоге нет; связи между его таблицами можно посмотреть функцией pg_get_catalog_foreign_keys().', 'Объявленных ограничений FOREIGN KEY нет; функция pg_get_catalog_foreign_keys() описывает связи, но сервер их не проверяет.'),
        ('explanation', 'Что появилось у большинства таблиц системного каталога начиная с PostgreSQL 14?', NULL, NULL, 'Большинство таблиц каталога использует в качестве первичного ключа столбец oid.', 'В PostgreSQL 14 уникальные индексы таблиц каталога оформили как ограничения PRIMARY KEY и UNIQUE; у большинства таблиц первичный ключ — столбец oid.'),
        ('option', 'Почему не рекомендуется давать собственным таблицам имена с префиксом pg_?', 'Чтобы не конфликтовать с объектами системного каталога', 'Из-за риска конфликта с системными именами', 'Все таблицы и представления каталога начинаются с pg_.', 'Таблицы и представления каталога начинаются с pg_, и новая версия может добавить объект с тем же именем.'),
        ('option', 'Почему не рекомендуется давать собственным таблицам имена с префиксом pg_?', 'Такие имена запрещены для таблиц и схем', 'Из-за запрета CREATE TABLE на такие имена', 'Для таблиц они разрешены, хотя и не рекомендуются; для схем и табличных пространств префикс pg_ зарезервирован.', 'CREATE TABLE такое имя примет; префикс pg_ зарезервирован для имён схем и табличных пространств.'),
        ('option', 'Почему не рекомендуется давать собственным таблицам имена с префиксом pg_?', 'Такие объекты не попадают в резервные копии', 'Из-за исключения таких таблиц из pg_dump', 'Префикс имени на резервное копирование не влияет.', 'pg_dump выгружает такие таблицы как обычные: префикс имени на резервное копирование не влияет.'),
        ('option', 'Почему не рекомендуется давать собственным таблицам имена с префиксом pg_?', 'Такие объекты становятся общими для кластера', 'Из-за их размещения в общем каталоге кластера', NULL, NULL),
        ('explanation', 'Почему не рекомендуется давать собственным таблицам имена с префиксом pg_?', NULL, NULL, 'Префикс pg_ используется системными объектами; собственное такое имя может конфликтовать с текущим или будущим объектом каталога.', 'Префикс pg_ используется системными объектами; таблица с таким именем может конфликтовать с текущим или будущим объектом каталога.'),
        ('option', 'Что из перечисленного — общий для всего кластера объект системного каталога?', 'Список таблиц каждой базы (pg_class)', 'Список отношений (pg_class)', NULL, NULL),
        ('option', 'Что из перечисленного — общий для всего кластера объект системного каталога?', 'Столбцы таблиц каждой базы (pg_attribute)', 'Список столбцов таблиц (pg_attribute)', NULL, NULL),
        ('option', 'Что из перечисленного — общий для всего кластера объект системного каталога?', 'Функции каждой базы (pg_proc)', 'Список функций (pg_proc)', NULL, NULL),
        ('option', 'Что верно для типа данных oid?', 'Служит первичным ключом большинства таблиц каталога', 'Используется в ключах таблиц каталога', NULL, NULL),
        ('option', 'Что представляет собой тип данных oid?', '32-битный числовой идентификатор объекта', '32-битный целочисленный идентификатор объекта', NULL, NULL),
        ('option', 'Что представляет собой тип данных oid?', '64-битный числовой идентификатор объекта', '64-битный целочисленный идентификатор объекта', NULL, NULL),
        ('option', 'Для чего нужны типы reg*, например regclass?', 'Для преобразования имён объектов в oid', 'Для преобразования между именами и oid', NULL, NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
